public static class MultiBufferSource {
    com.mojang.blaze3d.vertex.BufferBuilder opaqueBuf;
    boolean hasQuads;

    void beginBatch() {
        if (opaqueBuf == null) {
            opaqueBuf = GodWandGeometry.begin(com.mojang.renderpearl.api.pipeline.PrimitiveTopology.QUADS, DefaultVertexFormat.POSITION_TEX_COLOR);
            hasQuads = false;
        }
    }

    public void endBatch() {
        if (opaqueBuf != null) {
            var built = hasQuads ? opaqueBuf.build() : null;
            opaqueBuf = null;
            hasQuads = false;
            if (built != null) {
                GodWandGeometry.disableBlend();
                GodWandGeometry.defaultBlendFunc();
                GodWandGeometry.enableDepthTest();
                GodWandGeometry.depthMask(true);
                GodWandGeometry.disableCull();
                GodWandGeometry.dominion(false);
                GodWandGeometry.bluered(false);
                GodWandGeometry.textured();
                GodWandGeometry.setShaderTexture(0, net.minecraft.client.renderer.texture.TextureAtlas.LOCATION_BLOCKS);
                GodWandGeometry.setShaderColor(1f, 1f, 1f, 1f);
                GodWandGeometry.draw(built);
                GodWandGeometry.colored();
            }
        }
    }

    public static final class BufferSource extends MultiBufferSource {}
}

private static final BlockRenderDispatcher DOMINION_BLOCK_RENDERER = new BlockRenderDispatcher();

private static final class BlockRenderDispatcher {
    private final java.util.List<net.minecraft.client.renderer.block.dispatch.BlockStateModelPart> parts = new java.util.ArrayList<>();
    private final net.minecraft.util.RandomSource rand = net.minecraft.util.RandomSource.createThreadLocalInstance(42L);
    private final Vector3f tmpPos = new Vector3f();

    void renderSingleBlock(BlockState state, PoseStack matrices, MultiBufferSource bufferSource, int light, int overlay) {
        if (bufferSource == null) return;
        bufferSource.beginBatch();
        Minecraft mc = Minecraft.getInstance();
        var model = mc.getModelManager().getBlockStateModelSet().get(state);
        parts.clear();
        rand.setSeed(42L);
        model.collectParts(rand, parts);
        Matrix4f pose = matrices.last().pose();
        var colors = mc.getBlockColors();
        int bl = net.minecraft.util.LightCoordsUtil.block(light);
        int sl = net.minecraft.util.LightCoordsUtil.sky(light);
        float lightShade = Mth.clamp(0.26f + 0.74f * (Math.max(bl, sl) / 15.0f), 0.26f, 1.0f);
        for (var part : parts) {
            for (var dir : net.minecraft.core.Direction.values()) {
                for (var q : part.getQuads(dir)) emitQuad(state, colors, pose, bufferSource, q, lightShade);
            }
            for (var q : part.getQuads(null)) emitQuad(state, colors, pose, bufferSource, q, lightShade);
        }
    }

    private void emitQuad(BlockState state, net.minecraft.client.color.block.BlockColors colors, Matrix4f pose,
                          MultiBufferSource buf, net.minecraft.client.resources.model.geometry.BakedQuad q, float lightShade) {
        float dirShade = switch (q.direction()) {
            case UP -> 1.0f;
            case DOWN -> 0.52f;
            case NORTH, SOUTH -> 0.80f;
            case EAST, WEST -> 0.64f;
        };
        float shade = dirShade * lightShade;
        int r = 255, g = 255, b = 255;
        int ti = q.materialInfo().tintIndex();
        if (ti >= 0) {
            var src = colors.getTintSource(state, ti);
            if (src != null) {
                int tint = src.color(state);
                r = (tint >> 16) & 0xFF;
                g = (tint >> 8) & 0xFF;
                b = tint & 0xFF;
            }
        }
        int cr = Mth.clamp((int) (r * shade), 0, 255);
        int cg = Mth.clamp((int) (g * shade), 0, 255);
        int cb = Mth.clamp((int) (b * shade), 0, 255);
        for (int v = 0; v < 4; v++) {
            var p = q.position(v);
            tmpPos.set(p.x(), p.y(), p.z()).mulPosition(pose);
            long uv = q.packedUV(v);
            float u = net.minecraft.client.model.geom.builders.UVPair.unpackU(uv);
            float tv = net.minecraft.client.model.geom.builders.UVPair.unpackV(uv);
            buf.opaqueBuf.addVertex(tmpPos.x, tmpPos.y, tmpPos.z).setUv(u, tv).setColor(cr, cg, cb, 255);
        }
        buf.hasQuads = true;
    }
}

