    BlockPos lightPos = BlockPos.containing(worldPos);
    if (world.getBlockState(lightPos).isSolidRender()) lightPos = owner.blockPosition().above();
    return net.minecraft.util.LightCoordsUtil.getLightCoords(world, lightPos);
}

